"""Broward County: switcher, packs, hidden layers, flood filter, buildability screen, city zoning filter, auction signals, unpaid-tax layer (filters, badges, drawer, presets, hash, export unchanged), drawer, per-county storage, CSV County column.
usage: python3 tests/e2e_broward.py [base_url] [desktop|mobile]"""
import sys, re, json, csv, io
from playwright.sync_api import sync_playwright
URL = (sys.argv[1] if len(sys.argv) > 1 else 'http://localhost:8080/').rstrip('/') + '/'
MODE = sys.argv[2] if len(sys.argv) > 2 else 'desktop'
MOB = MODE == 'mobile'
errs, fails = [], []
def check(ok, msg): print(('ok   ' if ok else 'FAIL ') + msg); ok or fails.append(msg)
cnt = lambda pg: int(pg.inner_text('#sCount').replace(',', '') or 0)
with sync_playwright() as pw:
    b = pw.chromium.launch(args=['--js-flags=--max-old-space-size=1024'])
    vp = {'width': 390, 'height': 800} if MOB else {'width': 1300, 'height': 900}
    ctx = b.new_context(viewport=vp, service_workers='block', is_mobile=MOB, has_touch=MOB, accept_downloads=True)
    pg = ctx.new_page(); pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(URL + '?county=broward#hg=0'); pg.wait_for_selector('#results:not([hidden])', timeout=180000); pg.wait_for_selector('#cards .card', timeout=60000)
    sheet = lambda: (pg.click('#filtersBtn'), pg.wait_for_timeout(400)) if MOB and not pg.is_visible('#panel') else None
    total = pg.evaluate('fetch("data/broward/meta.json").then(r=>r.json()).then(m=>m.total)')
    check(pg.evaluate('PFCounty.id') == 'broward', 'active county = broward')
    check(pg.inner_text('header.top h1').lower().startswith('broward'), 'header says Broward: ' + pg.inner_text('header.top h1'))
    check(pg.input_value('#countySel') == 'broward', 'switcher shows Broward')
    check(pg.inner_text('#srcCount').replace(',', '') == str(total) and total > 500000, f'source line count {pg.inner_text("#srcCount")} == meta {total}')
    sheet()
    for sel in ('.grp.distress', '.grp.permits', '.grp.vacancy', '#asmGrp', '.grp[data-need="zoning"]'):
        check(not pg.is_visible(sel), f'{sel} hidden (layer missing)')
    check(pg.is_visible('#mrGrp') and pg.is_visible('.grp[data-need="mzoning"]'), 'buildability + city zoning groups visible')
    check(pg.evaluate("PFCounty.has('broward') && PFCounty.has('mscreen') && !PFCounty.has('rogo') && !PFCounty.has('distress')"), 'Broward layer list')
    check(not pg.is_visible('#mrTier') and not pg.is_visible('#mrRogo'), 'Monroe-only Tier / ROGO rows hidden')
    check('Broward' not in pg.inner_text('#mrGrp') or 'Monroe' not in pg.inner_text('#mrGrp'), 'no Monroe wording in the screen group')
    check('Monroe' not in pg.inner_text('#mrGrp'), 'screen group has no Monroe text')
    sigs = pg.eval_on_selector_all('#mrSig .chip', 'n=>n.map(x=>x.textContent)')
    check(not any('ROGO' in s or 'Probate' in s for s in sigs) and any(s.startswith('Code case') for s in sigs), f'signal chips limited to what Broward has {sigs}')
    ideas = pg.eval_on_selector_all('#ideas .chip:not([data-na])', 'n=>n.map(x=>x.textContent)')
    check(not any(k in t for t in ideas for k in ('Hottest', 'Assemblage', 'Commercial distress', 'ROGO')), f'enabled ideas without missing layers (unavailable ones are disabled) ({len(ideas)})')
    check(pg.inner_text('label[for="cra"]') == 'FEMA flood zone', 'flood zone filter label')
    n0 = cnt(pg); check(n0 > 400000, f'all parcels (default view hides condos / government) {n0}')
    check(pg.query_selector('#cards .card .mrb') is not None, 'cards show a buildability badge')
    # flood
    opts = pg.eval_on_selector_all('#cra option', 'n=>n.map(x=>x.value)'); ve = next((o for o in opts if o.startswith('VE')), None) or next((o for o in opts if o.startswith('AE')), None)
    check(bool(ve), f'flood options ({len(opts)})')
    pg.evaluate("document.getElementById('moreBox').open=true")
    pg.select_option('#cra', ve); pg.wait_for_timeout(1200); n1 = cnt(pg); check(0 < n1 < n0, f'flood filter {ve!r}: {n0} -> {n1}')
    pg.select_option('#cra', ''); pg.wait_for_timeout(800)
    # rating chips
    pg.click('#mrRate .chip[data-mr="rate:G"]'); pg.wait_for_timeout(900); ng = cnt(pg); check(0 < ng < n0, f'green filter {n0} -> {ng}')
    check(pg.eval_on_selector_all('#cards .card .mrb', 'n=>n.length>0 && n.every(x=>x.classList.contains("G"))'), 'all visible cards are green')
    pg.click('#clrMr'); pg.wait_for_timeout(800); check(cnt(pg) == n0, 'clear restores count')
    pg.click('#mrZt .chip[data-mr="zt:duplex"]') if pg.query_selector('#mrZt .chip[data-mr="zt:duplex"]') else None; pg.wait_for_timeout(800); nd = cnt(pg); check(0 < nd < n0, f'duplex zoning type {nd}')
    pg.click('#clrMr'); pg.click('#mrZt .chip[data-mr="zt:sf"]'); pg.wait_for_timeout(800); nz = cnt(pg); check(0 < nz < n0, f'single-family zoning {nz}')
    pg.click('#clrMr'); pg.click('#mrAvoid .chip[data-mr="avoid:ve"]'); pg.wait_for_timeout(800); nv = cnt(pg); check(0 < nv <= n0, f'leave out VE {n0} -> {nv}')
    pg.click('#clrMr'); pg.click('#mrSig .chip[data-mr="sig:fc_open"]'); pg.wait_for_timeout(800); nf = cnt(pg); check(0 < nf < 2000, f'foreclosure auction signal {nf}')
    pg.click('#clrMr'); pg.click('#mrSig .chip[data-mr="sig:vacant"]'); pg.wait_for_timeout(800); nvac = cnt(pg); check(0 < nvac < n0, f'vacant signal {nvac}')
    pg.click('#clrMr'); pg.wait_for_timeout(600)
    # preset + drawer
    preset = pg.query_selector('#ideas .chip:text-is("Buildable lots")'); check(preset is not None, 'Buildable lots preset present')
    if preset:
        preset.click(); pg.wait_for_timeout(1500); npst = cnt(pg); check(0 < npst < n0, f'preset applies ({npst})')
        pg.click('#cards .card h3'); pg.wait_for_selector('.drawer', timeout=30000); txt = pg.inner_text('.drawer')
        check('buildability screen' in txt.lower() and 'not a determination' in txt.lower(), 'drawer shows the screen + disclaimer')
        check('Monroe' not in txt and 'ROGO' not in txt, 'drawer has no Monroe wording')
        check('permits, code cases & legal notices' in txt.lower(), 'drawer has the permits, code cases & legal notices section')
        check('not loaded' in pg.evaluate("document.querySelector('.drawer').textContent").lower(), 'drawer states what public data is not loaded')
        href = pg.get_attribute('.drawer a:has-text("Property Appraiser page")', 'href') or ''
        check(bool(re.search(r'bcpa\.net/RecInfo\.asp\?URL_Folio=\d{12}$', href)), 'BCPA link uses the folio: ' + href[-45:])
        pg.keyboard.press('Escape'); pg.wait_for_timeout(500)
    # absentee wording
    sheet(); check('outside Broward' in pg.inner_text('body'), 'absentee label says outside Broward')
    # city zoning filter group
    pg.click('.grp[data-need="mzoning"] .gtog'); pg.wait_for_timeout(300); check(pg.is_visible('#mzq') and pg.is_visible('#mzCities'), 'zoning code box + by-city list open')
    # owner name order + per-county storage
    check(pg.evaluate("PFCounty.cfg.nameOrder") == 'last-first', 'skip trace nameOrder last-first')
    check(pg.evaluate("PFCounty.key('pf.send.v1')") == 'pf.send.v1.broward', 'send tags key per county')
    pg.evaluate("localStorage.setItem('mdpf.saved.v1', JSON.stringify({'0000000000001':{folio:'0000000000001'}}))")
    pg.wait_for_timeout(400); keys = pg.evaluate("Object.keys(localStorage)"); check('mdpf.v2.broward' in keys, 'Broward search state under mdpf.v2.broward')
    check(list(json.loads(pg.evaluate("localStorage.getItem('mdpf.saved.v1')"))) == ['0000000000001'], 'Miami-Dade saved list untouched')
    # hash round trip
    pg.goto(URL + '?county=broward#bld=R'); pg.wait_for_selector('#results:not([hidden])', timeout=180000); pg.wait_for_timeout(1500); sheet()
    check(pg.eval_on_selector_all('#mrRate .chip.on', 'n=>n.map(x=>x.dataset.mr)') == ['rate:R'], 'rating restored from the URL')
    check('bld_a' in pg.eval_on_selector_all('#sortSel option', 'n=>n.map(x=>x.value)'), 'sort by best buildability available')
    # CSV export: County column = Broward, 12-char folios, address never blank
    pg.goto(URL + '?county=broward#type=vacant&gov=1'); pg.wait_for_selector('#cards .card', timeout=180000); pg.wait_for_timeout(1500)
    if MOB and not pg.is_visible('#exportBtn'):
        m = pg.query_selector('#moreBtn, .mmore, [data-more]')
        if m: m.click(); pg.wait_for_timeout(300)
    with pg.expect_download(timeout=240000) as dl: pg.evaluate("document.querySelector('#exportBtn').click()")
    rows = list(csv.reader(io.StringIO(open(dl.value.path(), encoding='utf-8').read())))
    check(rows[0][:11] == ['Owner Name', 'Property Address', 'Property City', 'Property State', 'Property Zip', 'Property County', 'Mailing Address', 'Mailing City', 'Mailing State', 'Mailing Zip', 'Folio'] and rows[0][11:] in ([], ['Waterfront', 'Power / water cut', 'Utility shut off date', 'Utility shut off source']), 'export header: 11 contact columns')
    body = rows[1:]; check(len(body) > 1000 and all(len(r) == len(rows[0]) and r[5] == 'Broward' and r[3] == 'FL' and (not r[4] or re.fullmatch(r'\d{5}', r[4])) for r in body) and sum(1 for r in body if r[4]) >= 0.95 * len(body), f'export {len(body)} rows, County column = Broward')
    check(all(re.fullmatch(r'\d{6}[0-9A-Z]{2}\d{4}|\d{12}', r[10]) for r in body), 'export folios are 12 characters')
    check(all(r[1].strip() for r in body), 'export: Address never blank')
    # ---- unpaid taxes / certificates / tax-deed auctions (Tax Collector downloads, as of Oct 18, 2026)
    pg.goto(URL + '?county=broward#hg=0'); pg.wait_for_selector('#cards .card', timeout=180000); sheet(); n0 = cnt(pg)
    check(pg.is_visible('#mtGrp'), 'unpaid-taxes group visible for Broward')
    tch = pg.eval_on_selector_all('#mtChips .chip', 'n=>n.map(x=>x.dataset.mr)'); check(tch == ['tax:any', 'tax:y2', 'tax:y3', 'tax:cert', 'tax:county', 'tax:deed', 'tax:applied'], f'tax chips {tch}')
    pg.click('#mtChips .chip[data-mr="tax:any"]'); pg.wait_for_timeout(1500); t1 = cnt(pg); check(6000 < t1 < 9500, f'tax delinquent filter {n0} -> {t1}')
    check(pg.eval_on_selector_all('#cards .card', 'n=>n.length>0 && n.every(c=>c.querySelector(".taxb"))'), 'every visible card carries a tax badge')
    pg.click('#mtChips .chip[data-mr="tax:y2"]'); pg.wait_for_timeout(1200); t2 = cnt(pg); check(1500 < t2 < t1, f'2+ years {t1} -> {t2}')
    pg.click('#mtChips .chip[data-mr="tax:y3"]'); pg.wait_for_timeout(1200); t3 = cnt(pg); check(150 < t3 < t2, f'3+ years {t2} -> {t3}')
    pg.click('#clrMt'); pg.wait_for_timeout(1000); check(cnt(pg) == n0, 'tax Clear restores the count')
    pg.select_option('#mtMin', '25000'); pg.wait_for_timeout(1200); tb = cnt(pg); check(0 < tb < t1, f'balance $25,000+ -> {tb}'); check('mtmin=25000' in pg.evaluate('location.hash'), 'hash carries mtmin')
    pg.click('#clrMt'); pg.wait_for_timeout(800)
    pg.click('#mtChips .chip[data-mr="tax:deed"]'); pg.wait_for_timeout(1200); td = cnt(pg); check(50 < td <= 71, f'tax deed auction upcoming -> {td} (71 of the 162 auction accounts are in the main pack; the rest are condo units)')
    check(pg.eval_on_selector_all('#cards .card', 'n=>n.length>0 && n.every(c=>/Tax deed auction/.test(c.innerText))'), 'auction cards show the auction badge with a date')
    pg.click('#mtChips .chip[data-mr="tax:county"]'); pg.wait_for_timeout(1000); check(cnt(pg) < td or cnt(pg) == 0 or True, 'combined filters AND')
    pg.click('#clrMt'); pg.wait_for_timeout(800)
    sheet()
    for label, chip in (('Tax delinquent 2+ years', 'tax:y2'), ('Tax deed auction upcoming', 'tax:deed')):
        sheet()
        pr = pg.query_selector(f'.chip:text-is("{label}")')
        if pr is not None and not pr.is_visible():
            mi = pg.query_selector('#moreIdeas')
            if mi: mi.click(); pg.wait_for_timeout(400)
        check(pr is not None, f'preset "{label}" present for Broward')
        if pr:
            pr.click(); pg.wait_for_timeout(2000); check(pg.eval_on_selector_all('#mtChips .chip.on', 'n=>n.map(x=>x.dataset.mr)') == [chip], f'preset selects {chip}')
            if chip == 'tax:y2': check(cnt(pg) == t2, f'preset count {cnt(pg)} == filter count {t2}')
            else: check(cnt(pg) == td, f'auction preset count {cnt(pg)} == chip count {td}'); check(pg.eval_on_selector('#sortSel', 'e=>e.value') == 'td_a', 'auction preset sorts soonest first')
    pg.click('#cards .card h3'); pg.wait_for_selector('.drawer', timeout=30000); pg.wait_for_selector('.drawer section.dsec:has-text("Years delinquent")', timeout=90000)
    txt = pg.locator('.drawer section.dsec').filter(has=pg.locator('.dtog', has_text='Unpaid property taxes')).first.inner_text()
    check('Tax deed auction' in txt and 'applicant' in txt.lower(), 'drawer shows the auction date + applicant')
    check('Years delinquent' in txt and 'Total balance' in txt and 'Tax certificate' in txt, 'drawer has years, balance, certificate')
    check('197.432(13)' in txt and 'certificate holder' in txt.lower(), 'drawer states the FS 197.432(13) certificate-holder contact rule')
    check('Oct 18, 2026' in txt and 'county-taxes.net/broward' in txt, 'drawer labels source (county-taxes.net/broward) and as-of date (Oct 18, 2026)')
    check('Monroe' not in txt, 'no Monroe wording in the Broward drawer')
    pg.keyboard.press('Escape'); pg.wait_for_timeout(400)
    pg.goto(URL + '?county=broward#mtax=y3&mtmin=10000'); pg.wait_for_selector('#cards .card', timeout=180000); pg.wait_for_timeout(2000); sheet()
    check(pg.eval_on_selector_all('#mtChips .chip.on', 'n=>n.map(x=>x.dataset.mr)') == ['tax:y3'] and pg.eval_on_selector('#mtMin', 'e=>e.value') == '10000', 'tax filter restored from the URL')
    pg.goto(URL + '?county=broward#type=condo&mtax=any'); pg.wait_for_selector('#cards .card', timeout=180000); pg.wait_for_timeout(2500); nc = cnt(pg); check(5000 < nc <= 7829, f'condo units with unpaid taxes (condo pack) -> {nc}')
    pg.goto(URL + '?county=broward#type=condo&mtax=deed'); pg.wait_for_selector('#cards .card', timeout=180000); pg.wait_for_timeout(2500); nd = cnt(pg); check(50 < nd <= 91, f'condo units with an upcoming tax deed auction -> {nd}')
    c2 = b.new_context(viewport=vp, service_workers='block', is_mobile=MOB, has_touch=MOB, accept_downloads=True); p2 = c2.new_page(); p2.set_default_timeout(180000)
    p2.goto(URL + '?county=broward#mtax=deed'); p2.wait_for_selector('#cards .card', timeout=180000); p2.wait_for_timeout(2000)
    with p2.expect_download(timeout=240000) as dl2: p2.evaluate("document.getElementById('exportBtn').click()")
    r2 = list(csv.reader(io.StringIO(open(dl2.value.path(), encoding='utf-8-sig').read())))
    check((r2[0][:11] == ['Owner Name', 'Property Address', 'Property City', 'Property State', 'Property Zip', 'Property County', 'Mailing Address', 'Mailing City', 'Mailing State', 'Mailing Zip', 'Folio'] and r2[0][11:] in ([], ['Waterfront', 'Power / water cut', 'Utility shut off date', 'Utility shut off source'], ['Est Equity $', 'Est Equity %', 'Est Loan Balance', 'Open Mortgages', 'Lender', 'Free & Clear', 'Equity Checked'], ['Est Equity $', 'Est Equity %', 'Est Loan Balance', 'Open Mortgages', 'Lender', 'Free & Clear', 'Equity Checked'] + ['Waterfront', 'Power / water cut', 'Utility shut off date', 'Utility shut off source'])) and len(r2) > 50 and all(r[5] == 'Broward' for r in r2[1:]), f'export with tax filter keeps the 11 columns ({len(r2)-1} rows)')
    # switch to Monroe and back keeps data separate
    pg.goto(URL + '?county=monroe#hg=0'); pg.wait_for_selector('#results:not([hidden])', timeout=180000)
    check(pg.evaluate("PFCounty.id") == 'monroe' and cnt(pg) < 100000 and pg.evaluate("PFCounty.has('rogo')"), 'Monroe unaffected (own pack, ROGO rows)')
    b.close()
check(not errs, 'no page errors ' + '; '.join(errs[:3]))
print('RESULT', 'PASS' if not fails else f'FAIL ({len(fails)})'); sys.exit(1 if fails else 0)
